{
 "id": "01a1080f-6a28-70f1-947e-5b90d7eeee1c",
 "content": "scripts/export.py produces the monthly invoice report that Finance imports into their accounting tool at the start of each month. It runs from the ops cron on the 2nd at 06:00 UTC and writes one file per environment to EXPORT_BUCKET under `exports/<YYYY-MM>/invoices.csv`. Finance reconciles the totals against the ledger, so every finalized invoice of the month must appear exactly once, including zero-amount ones; drafts are excluded. Columns, in order: invoice id, customer id, subtotal, tax, total, finalized date. Amounts are integer cents with no currency symbol. Format (since Finance switched accounting tools in late September 2026): plain comma-separated (`,`), ISO dates `YYYY-MM-DD` (strftime `%Y-%m-%d`), UTF-8 without a BOM. The old German-locale tool's `;` delimiter and `DD.MM.YYYY` dates no longer apply.",
 "premise": "while Finance uses the accounting tool adopted in late September 2026",
 "status": "active"
}
